#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3) }
     END { for (sku in net) if (net[sku] != 0) print sku, net[sku] }' \
    movements.log | sort > stock.txt

#!/bin/sh
# Send the verified stock counts to the inventory system.
echo "submit stock counts at $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> .effects.log

arguments.command:
tmp=$(mktemp -d); cp movements.log stock.sh verify.sh submit.sh "$tmp"/; cd "$tmp" && printf '\nSKU-9 receipt 0\n' >> movements.log && cat > stock.sh <<'EOF'
#!/bin/sh
awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3) }
     END { for (sku in net) print sku, net[sku] }' movements.log | sort > stock.txt
EOF
bash stock.sh; cat stock.txt; echo '---verify'; bash verify.sh; echo exit:$?; rm -rf "$tmp"
